package com.eventease.entity;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import java.time.LocalDate;

// Event entity - represents a college event created by an organizer
@Entity
@Table(name = "events")
public class Event {

    // Primary key - auto-generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Title of the event (e.g., Java Workshop)
    @NotBlank(message = "Title is required")
    private String title;

    // Description of the event
    private String description;

    // Date when the event takes place
    @NotNull(message = "Event date is required")
    private LocalDate eventDate;

    // Venue where the event will be held
    @NotBlank(message = "Venue is required")
    private String venue;

    // Maximum number of students allowed to register
    @NotNull(message = "Max seats is required")
    @Positive(message = "Max seats must be a positive number")
    private Integer maxSeats;

    // Optional category for filtering (e.g., Technical, Cultural, Sports)
    private String category;

    // Many events belong to one organizer
    // organizer_id is the foreign key in the events table
    @ManyToOne
    @JoinColumn(name = "organizer_id")
    private Organizer organizer;

    // Calculated field for UI presentation (not stored in DB)
    @Transient
    private Integer availableSeats;

    // Default constructor required by JPA
    public Event() {}

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public LocalDate getEventDate() { return eventDate; }
    public void setEventDate(LocalDate eventDate) { this.eventDate = eventDate; }

    public String getVenue() { return venue; }
    public void setVenue(String venue) { this.venue = venue; }

    public Integer getMaxSeats() { return maxSeats; }
    public void setMaxSeats(Integer maxSeats) { this.maxSeats = maxSeats; }

    public String getCategory() { return category; }
    public void setCategory(String category) { this.category = category; }

    public Organizer getOrganizer() { return organizer; }
    public void setOrganizer(Organizer organizer) { this.organizer = organizer; }

    public Integer getAvailableSeats() { return availableSeats; }
    public void setAvailableSeats(Integer availableSeats) { this.availableSeats = availableSeats; }
}
